import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserException;
import org.apache.abdera.parser.ParserOptions;

/**
 * A thread‑safe, XXE‑protected provider for Atom feeds.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Shared Abdera engine – immutable after construction. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Whether to autodetect the charset of the incoming stream. */
    private boolean autodetectCharset;

    /* --------------------------------------------------------------------- */
    /* MessageBodyReader implementation                                       */
    /* --------------------------------------------------------------------- */

    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a parser instance from the shared engine.
        Parser parser = ATOM_ENGINE.getParser();

        // Create a fresh ParserOptions instance to avoid sharing mutable state
        // between threads.  Clone the defaults if they exist; otherwise start
        // from a clean slate.
        ParserOptions options = parser.getDefaultParserOptions();
        if (options == null) {
            options = new ParserOptions();
        } else {
            options = options.clone();
        }

        // Apply security‑relevant settings *before* parsing.
        options.setAutodetectCharset(autodetectCharset);
        options.setResolveEntities(false);   // Disable external entity resolution

        try {
            // Parse the input stream with the configured options.
            Document<T> doc = parser.parse(entityStream, options);
            return doc.getRoot();
        } catch (ParserException e) {
            // Wrap the Abdera exception in an IOException to match the method
            // signature and provide a clear error message.
            throw new IOException("Failed to parse Atom feed", e);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Other methods (MessageBodyWriter, utility methods, etc.) omitted      */
    /* --------------------------------------------------------------------- */
}
