import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name} as the base name.
     * The method validates {@code name} to prevent directory‑traversal attacks.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (may contain a query string)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if {@code name} resolves outside {@code dir}
     */
    public static File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("File name must not be null or empty");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths
        if (new File(name).isAbsolute()) {
            throw new IllegalArgumentException("Absolute paths are not allowed");
        }

        // Resolve and normalize the target path
        Path dirPath = dir.toPath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the resolved path is still under the target directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "File name escapes the target directory: " + name);
        }

        File file = targetPath.toFile();

        // Handle duplicate names by appending "-<index>"
        int dot = name.lastIndexOf('.');
        String prefix = (dot < 0) ? name : name.substring(0, dot);
        String suffix = (dot < 0) ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create parent directories if necessary
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
