import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public class JWTDecoder {

    /* --------------------------------------------------------------------- */
    /*  Whitelist of cryptographic algorithms that are considered safe.       */
    /*  The list can be extended as needed but should never contain "none".   */
    /* --------------------------------------------------------------------- */
    private static final Set<String> ALLOWED_ALGORITHMS =
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "HS256", "HS384", "HS512",
                    "RS256", "RS384", "RS512",
                    "ES256", "ES384", "ES512"
            )));

    /* --------------------------------------------------------------------- */
    /*  Decode a JWT string into a JWT object while enforcing strict checks.  */
    /* --------------------------------------------------------------------- */
    private JWT decode(String encodedJWT, Header header, String[] parts, Verifier verifier) {

        /* --------------------------------------------------------------- */
        /*  1. Validate the algorithm declared in the header.               */
        /* --------------------------------------------------------------- */
        String algName = header.algorithm.getName();
        if (algName == null || !ALLOWED_ALGORITHMS.contains(algName)) {
            throw new MissingVerifierException(
                    "Unsupported or missing algorithm [" + algName + "] in JWT header");
        }

        /* --------------------------------------------------------------- */
        /*  2. Reject unsigned tokens (no signature part).                  */
        /* --------------------------------------------------------------- */
        if (parts.length == 2) {
            throw new MissingVerifierException(
                    "Unsigned JWTs are not permitted (algorithm: " + algName + ")");
        }

        /* --------------------------------------------------------------- */
        /*  3. Ensure a verifier is supplied when a signature is present.   */
        /* --------------------------------------------------------------- */
        if (parts.length == 3 && verifier == null) {
            throw new MissingVerifierException(
                    "No Verifier has been provided for verifying a signature signed using [" + algName + "]");
        }

        /* --------------------------------------------------------------- */
        /*  4. Compute the message that was signed (header.payload).        */
        /* --------------------------------------------------------------- */
        int index = encodedJWT.lastIndexOf('.');
        if (index < 0) {
            throw new IllegalArgumentException("Malformed JWT: missing '.' separator");
        }
        byte[] message = encodedJWT.substring(0, index).getBytes(StandardCharsets.UTF_8);

        /* --------------------------------------------------------------- */
        /*  5. Verify the signature.                                        */
        /* --------------------------------------------------------------- */
        if (parts.length == 3) {
            byte[] signature = base64Decode(parts[2].getBytes(StandardCharsets.UTF_8));
            if (signature.length == 0) {
                throw new InvalidJWTSignatureException("Empty signature");
            }
            verifier.verify(header.algorithm, message, signature);
        }

        /* --------------------------------------------------------------- */
        /*  6. Deserialize the payload.                                     */
        /* --------------------------------------------------------------- */
        JWT jwt = Mapper.deserialize(
                base64Decode(parts[1].getBytes(StandardCharsets.UTF_8)),
                JWT.class);

        /* --------------------------------------------------------------- */
        /*  7. Validate standard claims.                                    */
        /* --------------------------------------------------------------- */
        if (jwt.isExpired()) {
            throw new JWTExpiredException();
        }
        if (jwt.isUnavailableForProcessing()) {
            throw new JWTUnavailableForProcessingException();
        }

        return jwt;
    }

    /* --------------------------------------------------------------------- */
    /*  Base64 decoding helper.                                            */
    /* --------------------------------------------------------------------- */
