import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Basic sanity checks – reject absolute paths and any attempt to traverse upwards
            if (entryName == null || entryName.isEmpty()
                    || entryName.contains("..")
                    || entryName.startsWith("/")
                    || entryName.startsWith("\\")) {
                throw new IOException("invalid entry name: " + entryName);
            }

            // Normalize the entry path and resolve it against the target directory
            Path entryPath = Paths.get(entryName).normalize();
            Path resolvedPath = targetDirPath.resolve(entryPath).normalize();

            // Ensure the resolved path is still within the target directory
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException("expanding " + entryName + " would create file outside of "
                        + targetDirectory);
            }

            File f = resolvedPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                File parent = f.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }
                try (OutputStream o = Files.newOutputStream(f.toPath())) {
                    writer.writeEntryDataTo(nextEntry, o);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
