    if (csize <= 0) {
        throw new IOException("Invalid entry size (" + csize + ") for STORED entry");
    }

    // If we've already read the declared size, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Refill the internal buffer if it has been exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {
            // End of underlying stream reached before the declared size.
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Calculate how many bytes remain for this entry.
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1;
    }

    // Determine the number of bytes to read in this call.
    int toRead = Math.min(buf.remaining(), length);
