    private String getAuthenticatedUserId(HttpServletRequest request) {
        String authUser = request.getHeader("X-Authenticated-User");
        if (authUser != null && !authUser.isEmpty()) {
            return authUser;
        }
        Object attr = request.getAttribute("authenticatedUserId");
        return (attr instanceof String) ? (String) attr : null;
    }

